@SpringBootTest(classes = ChaosMonkeyTestApplication.class, webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
@AutoConfigureTestRestTemplate
@ActiveProfiles("chaos-monkey")
@TestPropertySource(properties = { "management.endpoint.chaosmonkey.access=unrestricted", "management.endpoints.web.exposure.include=*", "spring.jmx.enabled=false" })
 class ChaosMonkeyRestEndpointApiTest {}
/**************TEST SETUP BEGIN*************/
@BeforeEach
void resetState(){
        chaosMonkeySettings.getChaosMonkeyProperties().setEnabled(false);
        AssaultProperties ap = chaosMonkeySettings.getAssaultProperties();
        ap.setLatencyActive(false);
        ap.setExceptionsActive(false);
        ap.setKillApplicationActive(false);
        ap.setLevel(1);
        ap.setLatencyRangeStart(1000);
        ap.setLatencyRangeEnd(3000);
        WatcherProperties wp = chaosMonkeySettings.getWatcherProperties();
        wp.setController(false);
        wp.setRestController(false);
        wp.setService(false);
        wp.setRepository(false);
        wp.setComponent(false);
    }
/**************TEST SETUP END*************/
/**************TEST METHOD BEGIN*************/
@Test
void postWatchersThenGetWatchers_roundTrip(){
        postJson(BASE + "/watchers", "{\"restController\": true, \"service\": true}");

        ResponseEntity<String> response = restTemplate.getForEntity(BASE + "/watchers", String.class);
        assertThat(response.getStatusCode()).isEqualTo(HttpStatus.OK);
        String body = response.getBody();
        assertThat((Boolean) JsonPath.read(body, "$.restController")).isTrue();
        assertThat((Boolean) JsonPath.read(body, "$.service")).isTrue();
    }
/**************TEST METHOD END*************/
/**************TEST HELPER METHOD BEGIN*************/
private ResponseEntity<String> postJson(String url, String body){
        HttpHeaders headers = new HttpHeaders();
        headers.setContentType(MediaType.APPLICATION_JSON);
        return restTemplate.exchange(url, HttpMethod.POST, new HttpEntity<>(body, headers), String.class);
    }
/**************TEST HELPER METHOD END*************/


